public readonly record struct Money(decimal Amount) : IComparable<Money>,
    IComparisonOperators<Money, Money, bool>
{
    public int CompareTo(Money other) => Amount.CompareTo(other.Amount);
    public static bool operator <(Money a, Money b) => a.Amount < b.Amount;
    public static bool operator >(Money a, Money b) => a.Amount > b.Amount;
    public static bool operator <=(Money a, Money b) => a.Amount <= b.Amount;
    public static bool operator >=(Money a, Money b) => a.Amount >= b.Amount;
}
// one generic algorithm for the whole family:
static T Max<T>(T a, T b) where T : IComparisonOperators<T, T, bool> => a < b ? b : a;
